#!/usr/bin/env python3
"""Migrate all data from Redis 8.10 (6379) to Valkey 9.1 (port arg), byte-exact:
every key in every db, types, values, key TTLs, hash-field TTLs, stream
consumer groups (entries-read counters, consumers, PEL assignment, delivery
counts, per-entry idle times)."""
import time, sys
import redis as redislib

DSTPORT = int(sys.argv[1]) if len(sys.argv) > 1 else 6380
SRC = redislib.Redis(host='127.0.0.1', port=6379)
DST = redislib.Redis(host='127.0.0.1', port=DSTPORT)

def now_ms(r):
    s, us = r.time()
    return int(s) * 1000 + us // 1000

def deadline(r, key, pttl):
    return None if pttl < 0 else now_ms(r) + pttl

def hflat(pairs):
    out = []
    for f, v in pairs: out += [f, v]
    return out

def copy_string(k):
    pttl = SRC.pttl(k)
    if pttl == -2: return
    v = SRC.get(k)
    DST.set(k, v)
    d = deadline(SRC, k, pttl)
    if d is not None: DST.execute_command('PEXPIREAT', k, d)

def copy_list(k):
    pttl = SRC.pttl(k)
    if pttl == -2: return
    DST.rpush(k, *SRC.lrange(k, 0, -1))
    d = deadline(SRC, k, pttl)
    if d is not None: DST.execute_command('PEXPIREAT', k, d)

def copy_set(k):
    pttl = SRC.pttl(k)
    if pttl == -2: return
    DST.sadd(k, *SRC.smembers(k))
    d = deadline(SRC, k, pttl)
    if d is not None: DST.execute_command('PEXPIREAT', k, d)

def copy_zset(k):
    pttl = SRC.pttl(k)
    if pttl == -2: return
    DST.zadd(k, {m: s for m, s in SRC.zrange(k, 0, -1, withscores=True)})
    d = deadline(SRC, k, pttl)
    if d is not None: DST.execute_command('PEXPIREAT', k, d)

def copy_hash(k):
    """returns True if this hash has field-level TTLs needing pass B"""
    pttl = SRC.pttl(k)
    if pttl == -2: return False
    d = deadline(SRC, k, pttl)
    pairs = SRC.hgetall(k)          # authoritative current content
    fields = list(pairs.keys())
    if not fields:
        # empty hash edge: mirror source existence
        if not SRC.exists(k): DST.delete(k)
        return False
    ttls = SRC.execute_command('HTTL', k, 'FIELDS', len(fields), *fields)
    DST.execute_command('HSET', k, *hflat(pairs.items()))
    has_fttl = any(t >= 0 for t in ttls)
    if not has_fttl:
        if d is not None: DST.execute_command('PEXPIREAT', k, d)
    return has_fttl

def finish_hash_field_ttls(k):
    """pass B: field expirations + the key expiration deferred from pass A."""
    pttl = SRC.pttl(k)
    if pttl == -2:
        DST.delete(k); return
    pairs = SRC.hgetall(k)
    fields = list(pairs.keys())
    if not fields:
        if not SRC.exists(k): DST.delete(k)
        return
    ttls = SRC.execute_command('HTTL', k, 'FIELDS', len(fields), *fields)
    ts = now_ms(SRC)
    ex = []
    for f, t in zip(fields, ttls):
        if t >= 0: ex += [f, ts + t]
    if ex: DST.execute_command('HPXPIREAT', k, 'FIELDS', len(ex) // 2, *ex)
    d = deadline(SRC, k, pttl)
    if d is not None: DST.execute_command('PEXPIREAT', k, d)

def parse_sid(b):
    s = b.decode() if isinstance(b, bytes) else str(b)
    t, q = s.split('-')
    return (int(t), int(q))

def fmt_sid(sid): return '%d-%d' % sid

def copy_stream(k):
    pttl = SRC.pttl(k)
    if pttl == -2: return
    d = deadline(SRC, k, pttl)
    info = SRC.xinfo_stream(k)
    mdei = parse_sid(info[b'max-deleted-entry-id'])
    lastgen = parse_sid(info[b'last-generated-id'])
    entries = SRC.xrange(k, min='-', max='+')
    if len(entries) == 0:
        if mdei == (0, 0):
            # empty stream (or stream never had entries): materialize shell
            DST.execute_command('XGROUP', 'CREATE', k, '_bootstrap_', '0', 'MKSTREAM')
            DST.execute_command('XGROUP', 'DESTROY', k, '_bootstrap_')
        else:
            # all entries deleted: materialize max-deleted-entry-id exactly
            DST.execute_command('XADD', k, fmt_sid(mdei), '_c', '_c')
            DST.execute_command('XDEL', k, fmt_sid(mdei))
            print(f'  ! {k!r}: empty stream, materialized mdei {mdei}', flush=True)
    else:
        for eid, ef in entries:
            DST.execute_command('XADD', k, fmt_sid(parse_sid(eid)), *hflat(ef.items()))
        live = {parse_sid(e[0]) for e in entries}
        if mdei != (0, 0) and mdei == lastgen and mdei not in live:
            DST.execute_command('XDEL', k, fmt_sid(mdei))
    # ---- consumer groups ----
    for g in SRC.xinfo_groups(k):
        gname = g[b'name'].decode()
        ld = parse_sid(g[b'last-delivered-id'])
        er_raw = g.get(b'entries-read')
        er = None if er_raw in (None, b'', '') else int(er_raw)
        DST.execute_command('XGROUP', 'CREATE', k, gname, fmt_sid(ld),
                            'ENTRIESREAD', er, 'MKSTREAM')
        # preserve exact counters (CREATE may have clamped)
        DST.execute_command('XGROUP', 'SETID', k, gname, fmt_sid(ld),
                            'ENTRIESREAD', er)
        # consumers (source idle times restored later via a claim of a PEL
        # entry, or forced via XREADGROUP '$' + reset below)
        cons = SRC.xinfo_consumers(k, gname)
        for c in cons:
            DST.execute_command('XGROUP', 'CREATECONSUMER', k, gname, c[b'name'].decode())
        # pending entries
        pel = []
        start = '-'
        while True:
            chunk = SRC.execute_command('XPENDING', k, gname, start, '+', 1000)
            if not chunk: break
            pel += chunk
            if len(chunk) < 1000: break
            start = '(' + fmt_sid(parse_sid(chunk[-1][0]))
        if pel:
            per_consumer = {}
            for p in pel:
                per_consumer.setdefault(p[1].decode(), []).append(fmt_sid(parse_sid(p[0])))
            # 1) insert PEL entries assigned to their consumers
            for cname, cids in per_consumer.items():
                DST.execute_command('XCLAIM', k, gname, cname, 0, *cids)
            # 2) restore delivery counts (each non-justid claim +1)
            for p in pel:
                cid = fmt_sid(parse_sid(p[0])); tgt = p[1].decode(); dc = p[3]
                for _ in range(dc - 1):
                    DST.execute_command('XCLAIM', k, gname, tgt, 0, cid)
            # 3) set exact per-entry idle ages as reported by source
            for p in pel:
                cid = fmt_sid(parse_sid(p[0])); tgt = p[1].decode()
                DST.execute_command('XCLAIM', k, gname, tgt, 0, cid,
                                    'IDLE', p[2], 'JUSTID')
        # consumer idle/inactive: entries are the only carrier; for consumers
        # with no PEL entries, idle can't be set directly -> leave as-is
    if d is not None: DST.execute_command('PEXPIREAT', k, d)

def copy_db(db):
    SRC.execute_command('SELECT', db); DST.execute_command('SELECT', db)
    keys = list(SRC.scan_iter(count=1000))
    print(f'db{db}: {len(keys)} keys', flush=True)
    deferred = []
    n = 0
    for k in sorted(keys):
        t = SRC.type(k).decode()
        if t == 'string': copy_string(k)
        elif t == 'list': copy_list(k)
        elif t == 'set': copy_set(k)
        elif t == 'zset': copy_zset(k)
        elif t == 'hash':
            if copy_hash(k): deferred.append(k)
        elif t == 'stream': copy_stream(k)
        else:
            print(f'  !! unknown type {t} for {k!r}', flush=True); sys.exit(1)
        n += 1
        if n % 1000 == 0: print(f'  {n} done', flush=True)
    for k in deferred:
        finish_hash_field_ttls(k)
    print(f'db{db}: copied ({len(deferred)} field-TTL hashes finalized)', flush=True)

t0 = time.time()
DST.execute_command('FLUSHALL')
# exact stream node packing like source
DST.config_set('stream-node-max-bytes', '0')
DST.config_set('stream-node-max-entries', '0')
for db in (0, 2):
    copy_db(db)
print(f'DONE in {time.time()-t0:.1f}s', flush=True)
