#!/usr/bin/env python3
"""Exact Redis 8.10 -> Valkey 9.1 data migration.
Copies every key in every db: same type, value, key TTL, hash-field TTLs,
streams with consumer groups (last-delivered-id, entries-read, consumers,
PEL assignment, delivery counts, idle times)."""
import socket, time, sys

class R:
    """minimal RESP2 client"""
    def __init__(self, host, port):
        self.s = socket.create_connection((host, port))
        self.f = self.s.makefile('rb')
    def cmd(self, *args):
        args = [a.encode() if isinstance(a, str) else a for a in args]
        out = b'*%d\r\n' % len(args) + b''.join(b'$%d\r\n%s\r\n' % (len(a), a) for a in args)
        self.s.sendall(out)
        return self._read()
    def _read(self):
        line = self.f.readline()[:-2]
        t, p = line[:1], line[1:]
        if t == b'+': return p
        if t == b'-': raise RuntimeError(p.decode())
        if t == b':': return int(p)
        if t == b'$':
            n = int(p)
            if n == -1: return None
            d = self.f.read(n); self.f.read(2); return d
        if t == b'*':
            n = int(p)
            if n == -1: return None
            return [self._read() for _ in range(n)]
        raise RuntimeError('bad reply %r' % line)

def pairs(flat):
    assert len(flat) % 2 == 0, flat
    return list(zip(flat[0::2], flat[1::2]))

SRC = R('127.0.0.1', 6379)
DST = R('127.0.0.1', int(sys.argv[1]) if len(sys.argv) > 1 else 6380)

def now_ms():
    s, us = pairs([SRC.cmd('TIME')])[0]
    return int(s) * 1000 + int(us) // 1000

def sid(b):  # 'ms-seq' -> (ms, seq)
    t, q = b.decode().split('-'); return (int(t), int(q))
def fsid(s): return '%d-%d' % s
def flatfv(d):  # {field: val} -> flat [f, v, ...]
    return [x for fv in d.items() for x in fv]

def xpending_all(k, g):
    out, start = [], '-'
    while True:
        rows = SRC.cmd('XPENDING', k, g, start, '+', 1000)
        if not rows: break
        out += rows
        if len(rows) < 1000: break
        start = b'(' + rows[-1][0]
    return out

def copy_string(k):
    pttl = SRC.cmd('PTTL', k)
    if pttl == -2: return
    SRC.cmd('SELECT', 0)
    DST.cmd('SET', k, SRC.cmd('GET', k))
    if pttl >= 0: DST.cmd('PEXPIREAT', k, now_ms() + pttl)

def copy_list(k):
    pttl = SRC.cmd('PTTL', k)
    if pttl == -2: return
    items = SRC.cmd('LRANGE', k, '0', '-1')
    if items: DST.cmd('RPUSH', k, *items)
    if pttl >= 0: DST.cmd('PEXPIREAT', k, now_ms() + pttl)

def copy_set(k):
    pttl = SRC.cmd('PTTL', k)
    if pttl == -2: return
    m = SRC.cmd('SMEMBERS', k)
    if m: DST.cmd('SADD', k, *m)
    if pttl >= 0: DST.cmd('PEXPIREAT', k, now_ms() + pttl)

def copy_zset(k):
    pttl = SRC.cmd('PTTL', k)
    if pttl == -2: return
    flat = SRC.cmd('ZRANGE', k, '0', '-1', 'WITHSCORES')
    if flat: DST.cmd('ZADD', k, *flat)
    if pttl >= 0: DST.cmd('PEXPIREAT', k, now_ms() + pttl)

def copy_hash(k):
    """returns True if hash needs pass-B field-TTL finalization"""
    pttl = SRC.cmd('PTTL', k)
    if pttl == -2: return False
    pairs_ = pairs(SRC.cmd('HGETALL', k))
    if not pairs_:
        if not SRC.cmd('EXISTS', k): DST.cmd('DEL', k)
        return False
    fields = [f for f, v in pairs_]
    ttls = SRC.cmd('HTTL', k, 'FIELDS', len(fields), *fields)
    gone = [f for f, t in zip(fields, ttls) if t == -2]
    if gone: DST.cmd('HDEL', k, *gone)
    DST.cmd('HSET', k, *flatfv(dict(pairs_)))
    if not any(t >= 0 for t in ttls):
        if pttl >= 0: DST.cmd('PEXPIREAT', k, now_ms() + pttl)
        return False
    return True

def finish_hash_field_ttls(k):
    pttl = SRC.cmd('PTTL', k)
    if pttl == -2:
        DST.cmd('DEL', k); return
    pairs_ = pairs(SRC.cmd('HGETALL', k))
    if not pairs_:
        if not SRC.cmd('EXISTS', k): DST.cmd('DEL', k)
        return
    fields = [f for f, v in pairs_]
    ttls = SRC.cmd('HTTL', k, 'FIELDS', len(fields), *fields)
    gone = [f for f, t in zip(fields, ttls) if t == -2]
    if gone: DST.cmd('HDEL', k, *gone)
    ts = now_ms()
    ex = [x for f, t in zip(fields, ttls) if t >= 0 for x in (f, ts + t)]
    if ex: DST.cmd('HPXPIREAT', k, 'FIELDS', len(ex) // 2, *ex)
    if pttl >= 0: DST.cmd('PEXPIREAT', k, ts + pttl)

def copy_stream(k):
    pttl = SRC.cmd('PTTL', k)
    if pttl == -2: return
    info = dict(pairs(SRC.cmd('XINFO', 'STREAM', k)))
    mdei = sid(info[b'max-deleted-entry-id'])
    lastgen = sid(info[b'last-generated-id'])
    entries = SRC.cmd('XRANGE', k, '-', '+')
    if not entries:
        if mdei == (0, 0):
            # empty stream shell (or never-had-entries): materialize via dummy group
            DST.cmd('XGROUP', 'CREATE', k, '_boot_', '0', 'MKSTREAM')
            DST.cmd('XGROUP', 'DESTROY', k, '_boot_')
        else:
            # whole stream deleted: exact last-generated-id = mdei
            DST.cmd('XADD', k, fsid(mdei), '_c', '_c')
            DST.cmd('XDEL', k, fsid(mdei))
            print(f'  ! {k!r}: empty w/ deleted tail, mdei={fsid(mdei)}', flush=True)
    else:
        for eid, ef in entries:
            DST.cmd('XADD', k, fsid(sid(eid)), *flatfv(dict(pairs(ef))))
        if mdei != (0, 0) and mdei == lastgen and mdei not in {sid(e[0]) for e in entries}:
            DST.cmd('XDEL', k, fsid(mdei))  # last entry was deleted
    # ---- consumer groups ----
    for gf in pairs(SRC.cmd('XINFO', 'GROUPS', k)):
        g = dict(gf)
        gname = g[b'name'].decode()
        ld = sid(g[b'last-delivered-id'])
        er_raw = g.get(b'entries-read')
        er = int(er_raw) if er_raw not in (None, b'') else None
        if er is None:
            DST.cmd('XGROUP', 'CREATE', k, gname, fsid(ld), 'MKSTREAM')
            DST.cmd('XGROUP', 'SETID', k, gname, fsid(ld))
        else:
            DST.cmd('XGROUP', 'CREATE', k, gname, fsid(ld), 'ENTRIESREAD', er, 'MKSTREAM')
            DST.cmd('XGROUP', 'SETID', k, gname, fsid(ld), 'ENTRIESREAD', er)
        pel = xpending_all(k, gname)
        # consumers with their PEL entries
        per_consumer = {}
        for p in pel:
            per_consumer.setdefault(p[1].decode(), []).append(fsid(sid(p[0])))
        for c in pairs(SRC.cmd('XINFO', 'CONSUMERS', k, gname)):
            cname = dict(c)[b'name'].decode()
            if cname not in per_consumer:
                DST.cmd('XGROUP', 'CREATECONSUMER', k, gname, cname)
        if pel:
            # 1) insert PEL entries, assigned to original consumers (auto-creates)
            for cname, cids in per_consumer.items():
                DST.cmd('XCLAIM', k, gname, cname, '0', 'FORCE', *cids)
            # 2) restore delivery counts (each non-JUSTID claim on existing PEL: +1)
            for p in pel:
                cid, tgt, dc = fsid(sid(p[0])), p[1].decode(), p[3]
                for _ in range(dc - 1):
                    DST.cmd('XCLAIM', k, gname, tgt, '0', cid)
            # 3) set exact per-entry idle ages
            for p in pel:
                cid, tgt, idle = fsid(sid(p[0])), p[1].decode(), p[2]
                DST.cmd('XCLAIM', k, gname, tgt, '0', cid, 'IDLE', idle, 'JUSTID')
    if pttl >= 0: DST.cmd('PEXPIREAT', k, now_ms() + pttl)

def copy_db(db):
    SRC.cmd('SELECT', db); DST.cmd('SELECT', db)
    cur, keys = b'0', []
    while True:
        cur, batch = SRC.cmd('SCAN', cur, 'COUNT', 1000)
        keys += batch
        if cur == b'0': break
    print(f'db{db}: {len(keys)} keys', flush=True)
    deferred = []
    for i, k in enumerate(sorted(keys)):
        t = SRC.cmd('TYPE', k).decode()
        if t == 'string': copy_string(k)
        elif t == 'list': copy_list(k)
        elif t == 'set': copy_set(k)
        elif t == 'zset': copy_zset(k)
        elif t == 'hash':
            if copy_hash(k): deferred.append(k)
        elif t == 'stream': copy_stream(k)
        else:
            print(f'  !! unknown type {t} for {k!r}', flush=True); sys.exit(1)
        if (i + 1) % 1000 == 0: print(f'  {i+1} done', flush=True)
    for k in deferred: finish_hash_field_ttls(k)
    print(f'db{db}: done ({len(deferred)} field-TTL hashes finalized)', flush=True)

t0 = time.time()
DST.cmd('FLUSHALL')
for db in (0, 2):
    copy_db(db)
print(f'DONE in {time.time()-t0:.1f}s', flush=True)
