        if sorted(fa) != sorted(fb): err(f'db{db} {k!r} hash fields mismatch')
        else:
            da, db_ = dict(zip(fa, va)), dict(zip(fb, vb))
            for f in fa:
                if da[f] != db_.get(f, b'<missing>'): err(f'db{db} {k!r} field {f!r} value mismatch')
        ta = SRC.cmd('HTTL', k, 'FIELDS', len(fa), *fa) if fa else []
        tb = DST.cmd('HTTL', k, 'FIELDS', len(fa), *fa) if fa else []
        for f, x, y in zip(fa, ta, tb):
            if (x < 0) != (y < 0): err(f'db{db} {k!r} field {f!r} fttl-persist {x} vs {y}')
            elif x >= 0 and not (-100 <= (y - x) <= 100): err(f'db{db} {k!r} field {f!r} fttl drift {x} vs {y}')
    elif t == 'stream':
        ia, ib = dict(pairs(SRC.cmd('XINFO', 'STREAM', k))), dict(pairs(DST.cmd('XINFO', 'STREAM', k)))
        for fld in (b'last-generated-id', b'max-deleted-entry-id', b'entries-added', b'recorded-first-entry-id'):
            if ia[fld] != ib[fld]:
                err(f'db{db} {k!r} stream {fld.decode()} {ia[fld]!r} vs {ib[fld]!r}')
        ea, eb = SRC.cmd('XRANGE', k, '-', '+'), DST.cmd('XRANGE', k, '-', '+')
        if ea != eb: err(f'db{db} {k!r} stream entries mismatch ({len(ea)} vs {len(eb)})')
        ga = [dict(pairs(g)) for g in SRC.cmd('XINFO', 'GROUPS', k)]
        gb = [dict(pairs(g)) for g in DST.cmd('XINFO', 'GROUPS', k)]
        ma = {g[b'name']: g for g in ga}; mb = {g[b'name']: g for g in gb}
        if set(ma) != set(mb): err(f'db{db} {k!r} group names {set(ma)} vs {set(mb)}')
        for name, g in ma.items():
            h = mb.get(name)
            if not h: continue
            for fld in (b'last-delivered-id', b'entries-read', b'lag', b'pending'):
                if g.get(fld) != h.get(fld):
                    err(f'db{db} {k!r} group {name!r} {fld.decode()} {g.get(fld)!r} vs {h.get(fld)!r}')
            ca = [dict(pairs(c)) for c in SRC.cmd('XINFO', 'CONSUMERS', k, name.decode())]
            cb = [dict(pairs(c)) for c in DST.cmd('XINFO', 'CONSUMERS', k, name.decode())]
            na = {c[b'name']: c for c in ca}; nb = {c[b'name']: c for c in cb}
            if set(na) != set(nb): err(f'db{db} {k!r} group {name!r} consumers {set(na)} vs {set(nb)}')
            for cn, c in na.items():
                d = nb.get(cn)
                if not d: continue
                if c[b'pending'] != d[b'pending']:
                    err(f'db{db} {k!r} group {name!r} consumer {cn!r} pending {c[b"pending"]} vs {d[b"pending"]}')
                for fld in (b'idle', b'inactive'):
                    x, y = c.get(fld), d.get(fld)
                    if not (x is None and y is None or (x is not None and y is not None and abs(y - x) <= 2500)):
                        err(f'db{db} {k!r} group {name!r} consumer {cn!r} {fld.decode()} {x} vs {y}')
            def pel(r):
                out, start = [], '-'
                while True:
                    rows = r.cmd('XPENDING', k, name.decode(), start, '+', 1000)
                    if not rows: break
                    out += rows
                    if len(rows) < 1000: break
                    start = b'(' + rows[-1][0]
                return out
            pa, pb = pel(SRC), pel(DST)
            dma = {sid(p[0]): (p[1], p[2], p[3]) for p in pa}
            dmb = {sid(p[0]): (p[1], p[2], p[3]) for p in pb}
            if set(dma) != set(dmb):
                miss = sorted(set(dma) - set(dmb)); extra = sorted(set(dmb) - set(dma))
                if miss: err(f'db{db} {k!r} group {name!r} pel missing ids: {[fsid(x) for x in miss[:3]]}')
                if extra: err(f'db{db} {k!r} group {name!r} pel extra ids: {[fsid(x) for x in extra[:3]]}')
            for i in set(dma) & set(dmb):
                a_, b_ = dma[i], dmb[i]
                if a_[0] != b_[0]: err(f'db{db} {k!r} group {name!r} pel {fsid(i)} consumer {a_[0]} vs {b_[0]}')
                if a_[2] != b_[2]: err(f'db{db} {k!r} group {name!r} pel {fsid(i)} delivery-count {a_[2]} vs {b_[2]}')
                if not (-100 <= (b_[1] - a_[1]) <= 100): err(f'db{db} {k!r} group {name!r} pel {fsid(i)} idle {a_[1]} vs {b_[1]}')

total_s = total_d = 0
for db in (0, 2):
    ks = keyset(SRC, db)
    dset = keyset(DST, db)
    SRC.cmd('SELECT', db); DST.cmd('SELECT', db)
    miss, extra = ks - dset, dset - ks
    # re-check missing/extra for legitimate expiry (sub-second TTL keys)
    if miss:
        res = SRC.pipe([('PTTL', k) for k in sorted(miss)])
        legit = {k for k, p in zip(sorted(miss), res) if p == -2 or (p >= 0 and p < 200)}
        miss -= legit
    if extra:
        res = SRC.pipe([('PTTL', k) for k in sorted(extra)])
        legit = {k for k, p in zip(sorted(extra), res) if p == -2 or (p >= 0 and p < 200)}
        extra -= legit
    if miss: err(f'db{db}: {len(miss)} keys missing on dst: {sorted(miss)[:5]}')
    if extra: err(f'db{db}: {len(extra)} extra keys on dst: {sorted(extra)[:5]}')
    print(f'db{db}: src={len(ks)} dst={len(dset)}', flush=True)
    total_s += len(ks); total_d += len(dset)
    for i, k in enumerate(sorted(ks)):
        check_key(db, k)
        if (i+1) % 1000 == 0: print(f'  verified {i+1}', flush=True)
print(f'TOTALS: src={total_s} dst={total_d}  verify-took={time.time()-t_start:.1f}s')
print('RESULT:', 'ALL OK' if not errors else f'{len(errors)} FAILURES')
